import React, { useState } from 'react';

const QuizPage = () => {
        const [formData, setFormData] = useState({
                exam: "",
                difficultyLevels: [],
                classYear: "",
                name: "",
                quizMode: "",
                addHints: false,
                adaptiveDifficulty: false,
                answerExplanation: false,
                breakIntoSubtopics: false,
                subjects: [],
                topics: [],
                currentSubject: "",
                currentTopic: "",
                numberOfQuestions: null,
                timerOption: "noTimer", // Default timer option
                perQuestionTime: "", // Minutes per question
                totalTime: "", // Total quiz time
              });

              // Function to handle input changes
              const handleChange = (e) => {
                const { name, value, type, checked } = e.target;
                setFormData((prevData) => ({
                  ...prevData,
                  [name]: type === "checkbox" ? checked : value,
                }));
              };

              const handleDifficultyChange = (e) => {
                const { value, checked } = e.target;
                setFormData((prevData) => ({
                  ...prevData,
                  difficultyLevels: checked
                    ? [...prevData.difficultyLevels, value]
                    : prevData.difficultyLevels.filter((level) => level !== value),
                }));
              };

              const handleAddSubject = () => {
                if (formData.currentSubject.trim()) {
                  setFormData((prev) => ({
                    ...prev,
                    subjects: [...prev.subjects, formData.currentSubject.trim()],
                    currentSubject: "", // Clear the input after adding
                  }));
                }
              };

              const handleAddTopic = () => {
                if (formData.currentTopic.trim()) {
                  setFormData((prev) => ({
                    ...prev,
                    topics: [...prev.topics, formData.currentTopic.trim()],
                    currentTopic: "", // Clear the input after adding
                  }));
                }
              };

              const handleTimerChange = (e) => {
                const { value } = e.target;
                setFormData((prev) => ({
                  ...prev,
                  timerOption: value,
                  perQuestionTime: "", // Reset related fields
                  totalTime: "",
                }));
              };

              const handleInputChange = (e) => {
                const { name, value } = e.target;
                setFormData((prev) => ({
                  ...prev,
                  [name]: value,
                }));
              };

              const handleSubmit = (event) => {
                event.preventDefault();
                // Log the complete form data
                console.log(formData);
              };


        return (
                <div>
                        <form onSubmit={handleSubmit}>

                                <h3>What should we call you?</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. ABC XYZ"
                                        name="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                />

                                <h3>Exam Type</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. MidTerm, JEE"
                                        name="exam"
                                        value={formData.exam}
                                        onChange={handleChange}
                                />

                                <h3>No. of Questions</h3>
                                <input
                                        type="number"
                                        placeholder="e.g. 5, 10"
                                        name="numberOfQuestions"
                                        value={formData.numberOfQuestions}
                                        onChange={handleChange}
                                />

                                <label className="block font-semibold">Select Difficulty Levels</label>
                                <div>
                                        <label>
                                                <input
                                                        type="checkbox"
                                                        value="Easy"
                                                        checked={formData.difficultyLevels.includes('Easy')}
                                                        onChange={handleDifficultyChange}
                                                />
                                                Easy
                                        </label>
                                        <label>
                                                <input
                                                        type="checkbox"
                                                        value="Medium"
                                                        checked={formData.difficultyLevels.includes('Medium')}
                                                        onChange={handleDifficultyChange}
                                                />
                                                Medium
                                        </label>
                                        <label>
                                                <input
                                                        type="checkbox"
                                                        value="Hard"
                                                        checked={formData.difficultyLevels.includes('Hard')}
                                                        onChange={handleDifficultyChange}
                                                />
                                                Hard
                                        </label>
                                </div>

                                <h3>Class / College Year</h3>
                                <input
                                        type="text"
                                        placeholder="e.g. class 11, 3rd Year"
                                        name="classYear"
                                        value={formData.classYear}
                                        onChange={handleChange}
                                />

                                <h3>Additional Features</h3>

                                <label>Add Hints</label>
                                <input
                                        type="checkbox"
                                        name="addHints"
                                        checked={formData.addHints}
                                        onChange={handleChange}
                                />

                                <label>Adaptive Difficulty</label>
                                <input
                                        type="checkbox"
                                        name="adaptiveDifficulty"
                                        checked={formData.adaptiveDifficulty}
                                        onChange={handleChange}
                                />

                                <label>Include Answer Explanation</label>
                                <input
                                        type="checkbox"
                                        name="answerExplanation"
                                        checked={formData.answerExplanation}
                                        onChange={handleChange}
                                />

                                <label>Break into Subtopics</label>
                                <input
                                        type="checkbox"
                                        name="breakIntoSubtopics"
                                        checked={formData.breakIntoSubtopics}
                                        onChange={handleChange}
                                />

                                {/* Subjects Section */}
                                <div className="mb-6">
                                        <h3 className="text-lg font-semibold mb-2">Subjects</h3>
                                        <div className="flex items-center gap-4 mb-2">
                                                <input
                                                        type="text"
                                                        name="currentSubject"
                                                        value={formData.currentSubject}
                                                        onChange={handleInputChange}
                                                        placeholder="Enter subject"
                                                        className="p-2 border border-gray-300 rounded-md flex-1"
                                                />
                                                <button
                                                        type="button"
                                                        onClick={handleAddSubject}
